write('NATIVE_PNG_INDEX.json',{'uid':UID,'attempts':attempts,'nativeImages':len(attempts),'approvedBodySheets':6,'approvedPoses':72,'rejectedNativeImages':1,'pixelEdits':0,'generatedOtherOCs':0})
delivery={'schema':'cqc.native-combat-delivery/1','uid':UID,'name':'OLD SNAKE','game':'Metal Gear Solid 4: Guns of the Patriots (2008), original PlayStation3','incarnation':'Original2008 PS3 Old Snake base gray OctoCamo, bandana and anatomicalLEFT Solid Eye, original Mk.2 loadout; no Touch/MPO/FaceCamo alternate','selectedCostume':'original-ps3-old-snake-gray-octocamo-left-solid-eye','basis':'Original Mk.2 tranquilizer pistol identity, opaque OctoCamo surface matching and physical veteran CQC; selected Chaff throw silhouette, no invented damaging explosion or optical attack.','displayHeight':230,'coverage':'action-frames','facing':1,'mirror':False,'sourceFiles':final,'actionLayout':layout,'actionMap':slots,'phaseMap':phase,'review':review,'nativeSourceCombatOrigins':str(B/'SOURCE_COMBAT_ORIGINS.json'),'limits':limits}
write('FINAL_DELIVERY.json',delivery)
write('REFERENCE_PRESERVATION_INDEX.json',{'uid':UID,'selectedCanonicalReferences':len(refs),'selectedImageBytes':sum(r['bytes'] for r in refs),'budgetBytes':15000000,'allRetainedResearchAndReferenceImageBytes':sum(p.stat().st_size for p in (B/'references').glob('*') if p.suffix.lower() in {'.png','.jpg','.gif'}),'rawUnselectedFrames':[1200,1600,1800,1950,2050,2300,2400],'originalSourceContractUnchanged':sha(B/'references/source-contract.json')==sha('/workspace/cqc-pass7-reference-selection/core__old_snake/source-contract.json'),'fullMoviesDownloaded':0,'nativeFramebufferImagesUnmodified':True,'references':[{'path':str(p.relative_to(B)),'bytes':p.stat().st_size,'sha256':sha(p),'selectedCanonical':str(p) in {r['file'] for r in refs}} for p in sorted((B/'references').rglob('*')) if p.is_file()]})
